async function killCaches(){try{if('serviceWorker'in navigator){const regs=await navigator.serviceWorker.getRegistrations();for(const r of regs)await r.unregister()}if('caches'in window){const keys=await caches.keys();await Promise.all(keys.map(k=>caches.delete(k)))}}catch(e){}}
function saveProfile(){const p={age:$('#age').value,sex:$('#sex').value,background:$('#background').value,language:$('#language').value};localStorage.setItem(STORE,JSON.stringify(p));applyProfile(p)}
function loadProfile(){try{const p=JSON.parse(localStorage.getItem(STORE)||'null');if(!p)return null;$('#age').value=p.age||'';$('#sex').value=p.sex||'prefer-not';$('#background').value=p.background||'prefer-not';$('#language').value=p.language||'nl';applyProfile(p);return p}catch{return null}}
function getProfile(){try{return JSON.parse(localStorage.getItem(STORE)||'{}')}catch{return {}}}
function applyProfile(p=getProfile()){const colors={european:['#ffe0cc','#d39b7e','#8b5a49'],african:['#c98d63','#7b432d','#3a1f18'],mena:['#e2ad82','#a66745','#5a3427'],'south-asian':['#d9a36e','#8b5638','#4f2d21'],'east-asian':['#ffe1c8','#c58b63','#7b4f38'],'se-asian':['#d8a16d','#8c5a38','#4b2c1d'],latin:['#e0a46f','#9a6040','#583424'],other:['#e1a978','#8f5c3e','#4a2e22'],'prefer-not':['#ffd8c2','#c99478','#8b5d4c']};let c=colors[p.background||'prefer-not']||colors['prefer-not'];$('#skinHi').setAttribute('stop-color',c[0]);$('#skinMid').setAttribute('stop-color',c[1]);$('#skinLo').setAttribute('stop-color',c[2]);const child=Number(p.age)>0&&Number(p.age)<16;$('#underwearLayer').classList.toggle('hidden',!child);$('#profileStatus').textContent=child?'Kindprofiel: veilige atlas':'Atlas afgestemd op profiel'}
function showProfile(){ $('#profileGate').classList.remove('hidden') } function hideProfile(){ $('#profileGate').classList.add('hidden') }

function renderLayers(){ $('#layerTabs').innerHTML=Object.entries(LAYERS).map(([k,l])=>`<button class="layer-btn ${state.layer===k?'active':''}" data-layer="${k}">${l.label}</button>`).join(''); $$('#layerTabs button').forEach(b=>b.onclick=()=>{state.layer=b.dataset.layer;state.selected=null;resetView(false);renderAll()}) }
function renderAll(){const layer=LAYERS[state.layer];$('#viewerTitle').textContent=layer.label;$('#viewerSubtitle').textContent=state.layer==='body'?'Klik op een lichaamsgebied of kies een anatomische laag.':'Klik op een structuur in deze laag.';$('#bodyDefault').classList.toggle('hidden',state.layer!=='body');$('#layerImage').classList.toggle('hidden',state.layer==='body');if(state.layer!=='body')$('#layerImage').src=layerToImage[state.layer];renderClickTargets();renderDetail();updateFlow();applyTransform();renderLayers();}
function renderClickTargets(){const host=$('#clickLayer');host.innerHTML='';(layerItems[state.layer]||layerItems.body).forEach(id=>{const d=DATA[id];if(!d)return;const b=document.createElement('button');b.className='click-hotspot'+(state.selected===id?' active':'');b.dataset.id=id;b.dataset.label=d.title;b.style.left=d.x+'%';b.style.top=d.y+'%';let size=Math.max(24,d.r*7);b.style.width=size+'px';b.style.height=size+'px';b.onclick=e=>{e.stopPropagation();select(id)};host.appendChild(b)})}
function select(id){state.selected=id;const d=DATA[id];if(d){state.zoom=Math.max(1.55,d.r<5?2.05:1.75);const v=$('#viewer').getBoundingClientRect();state.x=(50-d.x)*v.width/100*state.zoom;state.y=(50-d.y)*v.height/100*state.zoom;}renderClickTargets();renderDetail();updateFlow();applyTransform()}
function nearestByCoords(x,y){const list=layerItems[state.layer]||layerItems.body;let best=list[0],dist=1e9;list.forEach(id=>{const d=DATA[id];const dx=d.x-x,dy=d.y-y,dd=dx*dx+dy*dy;if(dd<dist){dist=dd;best=id}});return best}
function resetView(clear=true){state.zoom=1;state.x=0;state.y=0;if(clear)state.selected=null;applyTransform()}
function applyTransform(){const t=`translate(-50%,-50%) translate(${state.x}px,${state.y}px) scale(${state.zoom})`;$('#bodyDefault').style.transform=t;$('#layerImage').style.transform=t;$('#clickLayer').style.transform=`translate(${state.x}px,${state.y}px) scale(${state.zoom})`;$('#clickLayer').style.transformOrigin='50% 50%'}
function renderTabs(){const tabs={overview:'Uitleg',symptoms:'Klachten',redflags:'Alarmsignalen',prevention:'Preventie'};$('#detailTabs').innerHTML=Object.entries(tabs).map(([k,v])=>`<button class="detail-tab ${state.tab===k?'active':''}" data-tab="${k}">${v}</button>`).join('');$$('#detailTabs button').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;renderDetail()})}
function renderDetail(){renderTabs();const d=DATA[state.selected];if(!d){$('#detailTitle').textContent='Geen selectie';$('#detailSummary').textContent='Klik of tik op het lichaam. HealthLens selecteert het dichtstbijzijnde gebied of orgaan.';$('#breadcrumb').textContent='Geen selectie';$('#detailBody').innerHTML='<div class="info-card">Kies een lichaamsgebied of laag om uitleg, klachten, alarmsignalen en preventie te zien.</div>';return}$('#detailTitle').textContent=d.title;$('#detailSummary').textContent=d.summary;$('#breadcrumb').textContent=`${LAYERS[state.layer].label} › ${d.title}`;const label={overview:'Uitleg',symptoms:'Veelvoorkomende klachten',redflags:'Alarmsignalen',prevention:'Preventie'}[state.tab];$('#detailBody').innerHTML=`<div class="info-card"><strong>${d.system}</strong></div><div class="info-card"><strong>${label}</strong><ul>${(d[state.tab]||[]).map(x=>`<li>${x}</li>`).join('')}</ul></div><div class="info-card"><strong>Gerichte vragen</strong><ul>${(d.questions||[]).map(x=>`<li>${x}</li>`).join('')}</ul></div>`}
function updateFlow(){const d=DATA[state.selected];$('#activeSelectionChip').textContent=d?`${d.title} · ${d.system}`:'Nog geen selectie';$('#dynamicPrompt').innerHTML=d?`<strong>Gerichte vragen:</strong><br>${d.questions.join(' · ')}`:'Selecteer een gebied of orgaan voor gerichte vragen.';renderEducation()}
function renderEducation(){const d=DATA[state.selected];$('#educationPanel').innerHTML=d?`<div class="info-card"><strong>${d.title}</strong><p>${d.summary}</p></div><div class="info-card"><strong>Mogelijke verklaringsrichtingen</strong><ol>${d.diff.map(x=>`<li>${x}</li>`).join('')}</ol></div>`:'<div class="info-card">Selecteer een structuur voor verdiepende educatie.</div>'}
function renderFlags(){$('#redFlags').innerHTML=flags.map(f=>`<button class="layer-btn redflag" data-flag="${f}">${f}</button>`).join('');$$('.redflag').forEach(b=>b.onclick=()=>b.classList.toggle('active'))}
function renderKnowledge(){const cats=['Alles',...new Set(modules.map(m=>m[0]))];$('#knowledgeFilters').innerHTML=cats.map(c=>`<button class="layer-btn ${c==='Alles'?'active':''}" data-cat="${c}">${c}</button>`).join('');const draw=cat=>{ $$('#knowledgeFilters button').forEach(b=>b.classList.toggle('active',b.dataset.cat===cat));let list=cat==='Alles'?modules:modules.filter(m=>m[0]===cat);$('#knowledgeCards').innerHTML=list.map(m=>`<div class="mini-card"><b>${m[1]}</b><small>${m[2]}</small></div>`).join('')};$$('#knowledgeFilters button').forEach(b=>b.onclick=()=>draw(b.dataset.cat));draw('Alles')}
function setupSearch(){$('#atlasSearch').addEventListener('input',()=>{let q=$('#atlasSearch').value.trim().toLowerCase();if(q.length<2){$('#searchResults').classList.add('hidden');return}let res=Object.entries(DATA).filter(([id,d])=>[id,d.title,d.system,d.summary,...d.symptoms].join(' ').toLowerCase().includes(q)).slice(0,10);$('#searchResults').innerHTML=res.map(([id,d])=>`<button data-id="${id}"><strong>${d.title}</strong><br><small>${d.system}</small></button>`).join('')||'<button>Geen resultaat</button>';$('#searchResults').classList.remove('hidden');$$('#searchResults button[data-id]').forEach(b=>b.onclick=()=>{select(b.dataset.id);$('#atlasSearch').value='';$('#searchResults').classList.add('hidden')})})}
function analyze(){const d=DATA[state.selected],txt=$('#symptomText').value.trim(),sel=$$('.redflag.active').map(x=>x.dataset.flag),em=['druk op borst','benauwd','flauwvallen','scheve mond','krachtsverlies','spraakproblemen','hevige bloeding'];let cls='okText',title='Indicatief: niet-spoedeisend / observeer of plan beoordeling';if(sel.length){cls='warnText';title='Indicatief: medische beoordeling aanbevolen'}if(sel.some(f=>em.includes(f))){cls='dangerText';title='Indicatief: spoedbeoordeling kan nodig zijn'}let p=getProfile();let notes=[];if(d)notes.push(`Atlascontext: ${d.title}. ${d.summary}`);if(Number(p.age)>0&&Number(p.age)<16)notes.push('Onder 16: geen intieme foto/scans. Klachten kunnen wel veilig met tekst worden beschreven.');if(p.sex==='female'&&Number(p.age)>=38&&Number(p.age)<=55)notes.push('Profielcontext: hormonale/perimenopauzale context kan relevant zijn, zonder andere oorzaken uit te sluiten.');let diff=d?d.diff:['Selecteer eerst een gebied voor een betere differentiaal.'];$('#analysisResult').innerHTML=`<h3 class="${cls}">${title}</h3><p>${txt?`Omschrijving: ${txt}`:'Voeg klachttekst toe voor betere duiding.'}</p><p>Rode vlaggen: ${sel.length?sel.join(', '):'geen geselecteerd'}</p><div class="info-card"><strong>Indicatieve differentiaal</strong><ol>${diff.map(x=>`<li>${x}</li>`).join('')}</ol></div>${notes.map(n=>`<div class="info-card">${n}</div>`).join('')}<div class="info-card"><strong>Belangrijk</strong><br/>Dit is indicatief en geen diagnose. Bij twijfel of alarmsignalen: medische hulp.</div>`}
function bind(){let viewer=$('#viewer');viewer.addEventListener('pointerdown',e=>{state.drag=true;state.sx=e.clientX;state.sy=e.clientY;state.bx=state.x;state.by=state.y});window.addEventListener('pointermove',e=>{if(!state.drag)return;state.x=state.bx+e.clientX-state.sx;state.y=state.by+e.clientY-state.sy;applyTransform()});window.addEventListener('pointerup',()=>state.drag=false);viewer.addEventListener('click',e=>{if(Math.abs(e.clientX-state.sx)+Math.abs(e.clientY-state.sy)>8)return;let r=viewer.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*100,y=(e.clientY-r.top)/r.height*100;select(nearestByCoords(x,y))});viewer.addEventListener('wheel',e=>{e.preventDefault();state.zoom=Math.max(1,Math.min(4,state.zoom+(e.deltaY<0?.18:-.18)));applyTransform()},{passive:false});$('#zoomInBtn').onclick=()=>{state.zoom=Math.min(4,state.zoom+.25);applyTransform()};$('#zoomOutBtn').onclick=()=>{state.zoom=Math.max(1,state.zoom-.25);applyTransform()};$('#resetBtn').onclick=()=>{resetView(true);renderAll()};$('#profileBtn').onclick=showProfile;$('#bottomProfileBtn').onclick=e=>{e.preventDefault();showProfile()};$('#profileForm').onsubmit=e=>{e.preventDefault();saveProfile();hideProfile();renderAll()};$('#skipProfile').onclick=()=>{localStorage.setItem(STORE,JSON.stringify({age:'',sex:'prefer-not',background:'prefer-not',language:'nl'}));applyProfile({});hideProfile();renderAll()};$('#wipeProfile').onclick=()=>{localStorage.removeItem(STORE);$('#profileForm').reset();alert('Lokale gegevens gewist.')};$('#forceBtn').onclick=async()=>{await killCaches();location.href='stage1m.html?v='+Date.now()};$('#useForSymptoms').onclick=()=>{location.hash='symptoms';const d=DATA[state.selected];if(d&&!$('#symptomText').value.trim())$('#symptomText').value=`Klacht bij ${d.title}: `;$('#symptomText').focus()};$('#showPrevention').onclick=()=>{state.tab='prevention';renderDetail()};$('#analyzeBtn').onclick=analyze}
async function init(){await killCaches();let p=loadProfile();if(!p)showProfile();renderLayers();renderAll();renderFlags();renderKnowledge();setupSearch();bind()}
document.addEventListener('DOMContentLoaded',init);